static SEXP lmm_exact_random_table(SEXP labels, SEXP traits, const lmm_exact_tests *values, int *np)
{
    const char *names[] = {"term", "trait", "DF1", "DF2", "F", "p", "method", "status"};
    SEXP out = lmm_dataframe(values->nr, 8, names, np);
    SEXP denominator = lmm_keep(allocVector(STRSXP, values->nr), np);
    for (int j = 0; j < 8; j++)
        SET_VECTOR_ELT(out, j, allocVector(j < 2 || j > 5 ? STRSXP : REALSXP, values->nr));
    for (int i = 0; i < values->nr; i++)
    {
        int at = values->nf + 1 + i;
        SET_STRING_ELT(VECTOR_ELT(out, 0), i, STRING_ELT(labels, i));
        SET_STRING_ELT(VECTOR_ELT(out, 1), i, STRING_ELT(traits, 0));
        REAL(VECTOR_ELT(out, 2))[i] = values->numerator[at];
        REAL(VECTOR_ELT(out, 3))[i] = values->denominator[at];
        REAL(VECTOR_ELT(out, 4))[i] = values->statistic[at];
        REAL(VECTOR_ELT(out, 5))[i] = pf(values->statistic[at], values->numerator[at], values->denominator[at], FALSE, FALSE);
        SET_STRING_ELT(VECTOR_ELT(out, 6), i, mkChar("exact F"));
        SET_STRING_ELT(VECTOR_ELT(out, 7), i, mkChar("ok"));
        SET_STRING_ELT(denominator, i, mkChar(values->denominator_source[at]));
    }
    setAttrib(denominator, R_NamesSymbol, VECTOR_ELT(out, 0));
    setAttrib(out, install("denominator.source"), denominator);
    return out;
}

