static SEXP lmm_covariance_inputs(SEXP expression, SEXP env, int *np)
{
    while (lmm_is(expression, "(") && length(expression) == 2)
        expression = CADR(expression);
    int literal_list = lmm_is(expression, "list");
    if (TYPEOF(expression) == LANGSXP && lmm_is(CAR(expression), "::") &&
        length(CAR(expression)) == 3)
        literal_list = CADR(CAR(expression)) == install("base") &&
                       CADDR(CAR(expression)) == install("list");
    if (literal_list)
        for (SEXP node = CDR(expression); !isNull(node); node = CDR(node))
            if (lmm_is(CAR(node), "kro") &&
                lmm_native_getvar(install("kro"), env, 1) == R_UnboundValue)
                error("st.lmm: symbolic covariance products must be quoted, "
                      "for example \"kro(A,A)\". Use kronecker(M1,M2) "
                      "for actual R matrices");
    SEXP out = lmm_keep(eval(expression, env), np);
    if (isNull(out))
        return out;
    if (TYPEOF(out) != VECSXP)
        error("st.lmm: ucov must be a named list of matrices or quoted "
              "symbolic covariance requests");
    SEXP names = getAttrib(out, R_NamesSymbol);
    if (LENGTH(out) && (TYPEOF(names) != STRSXP ||
                        LENGTH(names) != LENGTH(out)))
        error("st.lmm: ucov entries must have nonempty unique term names");
    for (int k = 0; k < LENGTH(out); k++)
    {
        if (STRING_ELT(names, k) == NA_STRING ||
            !*CHAR(STRING_ELT(names, k)))
            error("st.lmm: ucov entry %d needs a nonempty term name", k + 1);
        for (int j = 0; j < k; j++)
            if (!strcmp(CHAR(STRING_ELT(names, j)),
                        CHAR(STRING_ELT(names, k))))
                error("st.lmm: duplicate ucov term '%s'",
                      CHAR(STRING_ELT(names, k)));
    }
    return out;
}

static int lmm_covariance_request(SEXP value, const char *term, int hybrid)
{
    if (TYPEOF(value) != STRSXP)
        return 0;
    if (LENGTH(value) != 1 || STRING_ELT(value, 0) == NA_STRING ||
        !*CHAR(STRING_ELT(value, 0)))
        error("st.lmm: ucov term '%s' requires one nonmissing, nonempty "
              "symbolic string or a numeric matrix", term);
    const char *text = CHAR(STRING_ELT(value, 0));
    int kind = !strcmp(text, "A") ? 1 : 0;
    if (!kind)
    {
        char token[32];
        int n = 0;
        for (const unsigned char *p = (const unsigned char *)text; *p; p++)
            if (!isspace(*p))
            {
                if (n == (int)sizeof(token) - 1)
                    break;
                token[n++] = *p;
            }
        token[n] = 0;
        if (!strcmp(token, "kro(A,A)") || !strcmp(token, "kro(a,a)"))
            kind = 2;
    }
    if (!kind)
        error("st.lmm: unsupported symbolic covariance '%s' for term '%s'. "
              "Use \"A\" or, for a hybrid parental interaction, "
              "\"kro(A,A)\"; strings are never evaluated as R code", text,
              term);
    if (kind == 2 && !hybrid)
        error("st.lmm: symbolic product '%s' for term '%s' requires a "
              "registered hybrid data set. Supply an actual numeric "
              "Kronecker matrix for other data", text, term);
    if (hybrid && kind == 1 && strchr(term, ':'))
        error("st.lmm: hybrid interaction term '%s' requires "
              "\"kro(A,A)\", not \"A\"", term);
    if (kind == 2 && !strchr(term, ':'))
        error("st.lmm: symbolic product '%s' requires a parental "
              "interaction term, not '%s'", text, term);
    return kind;
}

static SEXP lmm_dataset_covariances(SEXP expr, SEXP env, SEXP dataset,
                                    int hybrid, int *np)
{
    SEXP input = lmm_covariance_inputs(expr, env, np);
    int n = LENGTH(input), symbolic = 0;
    SEXP names = getAttrib(input, R_NamesSymbol);
    for (int k = 0; k < n; k++)
        symbolic |= TYPEOF(VECTOR_ELT(input, k)) == STRSXP;
    if (!symbolic)
        return input;
    SEXP out = lmm_keep(duplicate(input), np),
         terms = lmm_keep(allocVector(STRSXP, n), np), A = R_NilValue;
    for (int k = 0; k < n; k++)
    {
        SEXP value = VECTOR_ELT(input, k);
        const char *term = CHAR(STRING_ELT(names, k));
        int kind = lmm_covariance_request(value, term, hybrid);
        SET_STRING_ELT(terms, k, kind ? STRING_ELT(names, k) : mkChar(""));
        if (!kind)
            continue;
        if (hybrid)
            SET_VECTOR_ELT(out, k,
                           lmm_keep(h_kernel_export(
                               h_string(dataset, "hybrid.data.set"), term), np));
        else
        {
            if (isNull(A))
                A = lmm_keep(st_data_to_R(st_marker_A_values_cached(
                                 h_string(dataset, "data.set"), "0 1 2")), np);
            if (isNull(A))
                error("st.lmm: cannot construct A for marker data set '%s'",
                      CHAR(STRING_ELT(dataset, 0)));
            SET_VECTOR_ELT(out, k, A);
        }
    }
    setAttrib(out, install("st.symbolic.dataset"), dataset);
    setAttrib(out, install("st.symbolic.terms"), terms);
    return out;
}

static SEXP lmm_simulation_marker_data(SEXP, int *);

static lmm_arg_view *lmm_resolve_data_body_arguments(lmm_arg_view *args, int *np);
static lmm_arg_view *lmm_resolve_data_body_arguments(lmm_arg_view *args, int *np)
{
    SEXP env = lmm_arg_get(args, "envir");
    if (TYPEOF(env) != ENVSXP)
        return args;
    SEXP expr = lmm_arg_get(args, "data"), data;
    if (TYPEOF(expr) == SYMSXP &&
        lmm_native_getvar(expr, env, 1) == R_UnboundValue)
        error("st.lmm: data object '%s' was not found. Registered data set "
              "names must be quoted, for example data = \"%s\"",
              CHAR(PRINTNAME(expr)), CHAR(PRINTNAME(expr)));
    data = lmm_keep(eval(expr, env), np);
    SEXP ucov;
    if (TYPEOF(data) == STRSXP)
    {
        SEXP dataset = data;
        int hybrid = LENGTH(dataset) == 1 &&
                     STRING_ELT(dataset, 0) != NA_STRING &&
                     st_hybrid_name_exists(CHAR(STRING_ELT(dataset, 0)));
        data = lmm_keep(hybrid ? st_hybrid_marker_data(dataset)
                        : lmm_arg_logical(args, "simulation.data") == TRUE
                            ? lmm_simulation_marker_data(dataset, np)
                            : st_lmm_marker_data(dataset),
                        np);
        ucov = lmm_dataset_covariances(lmm_arg_get(args, "ucov"), env, dataset,
                                       hybrid, np);
    }
    else
    {
        ucov = lmm_covariance_inputs(lmm_arg_get(args, "ucov"), env, np);
        for (int k = 0; k < LENGTH(ucov); k++)
            if (TYPEOF(VECTOR_ELT(ucov, k)) == STRSXP)
                error("st.lmm: symbolic ucov term '%s' requires data to "
                      "name a registered data set; supply an actual matrix "
                      "when data is an R data frame or list",
                      CHAR(STRING_ELT(getAttrib(ucov, R_NamesSymbol), k)));
    }
    SEXP origin = getAttrib(ucov, install("st.symbolic.dataset"));
    if (!isNull(origin))
    {
        args = lmm_arg_put(args, "marker.dataset", origin, np);
        args = lmm_arg_put(args, "marker.terms",
                          getAttrib(ucov, install("st.symbolic.terms")), np);
    }
    args = lmm_arg_put(args, "data", data, np);
    return lmm_arg_put(args, "ucov", ucov, np);
}



typedef struct
{
    lmm_arg_view *args, *result;
    int *np;
    st_marker_validation_scope scope;
} lmm_resolve_context;

static SEXP lmm_resolve_data_scoped(void *payload)
{
    lmm_resolve_context *context = payload;
    context->result = lmm_resolve_data_body_arguments(context->args, context->np);
    return R_NilValue;
}

static void lmm_resolve_data_cleanup(void *payload)
{
    lmm_resolve_context *context = payload;
    st_marker_validation = context->scope.previous;
}

static lmm_arg_view *lmm_resolve_data_arguments(lmm_arg_view *args, int *np);
static lmm_arg_view *lmm_resolve_data_arguments(lmm_arg_view *args, int *np)
{
    lmm_resolve_context context = {args, NULL, np, {NULL, st_marker_validation}};
    st_marker_validation = &context.scope;
    R_ExecWithCleanup(lmm_resolve_data_scoped, &context,
                       lmm_resolve_data_cleanup, &context);
    return context.result;
}



