static SEXP lmm_hybrid_subset(SEXP x, const int *rows, int n, int *np)
{
    SEXP dim = getAttrib(x, R_DimSymbol);
    int old = isNull(dim) ? LENGTH(x) : INTEGER(dim)[0],
        columns = isNull(dim) ? 1 : LENGTH(x) / old;
    SEXP out = lmm_keep(allocVector(TYPEOF(x), (R_xlen_t)n * columns), np);
    for (int j = 0; j < columns; j++)
        for (int i = 0; i < n; i++)
        {
            R_xlen_t to = i + (R_xlen_t)n * j,
                     from = rows[i] + (R_xlen_t)old * j;
            switch (TYPEOF(x))
            {
            case REALSXP:
                REAL(out)[to] = REAL(x)[from];
                break;
            case INTSXP:
                INTEGER(out)[to] = INTEGER(x)[from];
                break;
            case LGLSXP:
                LOGICAL(out)[to] = LOGICAL(x)[from];
                break;
            case STRSXP:
                SET_STRING_ELT(out, to, STRING_ELT(x, from));
                break;
            case VECSXP:
                SET_VECTOR_ELT(out, to, VECTOR_ELT(x, from));
                break;
            case RAWSXP:
                RAW(out)[to] = RAW(x)[from];
                break;
            default:
                error("Unsupported hybrid performance column type");
            }
        }
    copyMostAttrib(x, out);
    if (!isNull(dim))
    {
        SEXP shape = lmm_keep(duplicate(dim), np);
        INTEGER(shape)[0] = n;
        setAttrib(out, R_DimSymbol, shape);
        SEXP dn = getAttrib(x, R_DimNamesSymbol);
        if (!isNull(dn))
        {
            dn = lmm_keep(duplicate(dn), np);
            SET_VECTOR_ELT(dn, 0, R_NilValue);
            setAttrib(out, R_DimNamesSymbol, dn);
        }
    }
    return out;
}

static void lmm_hybrid_full_check(SEXP expression, SEXP data, SEXP parents)
{
    if (TYPEOF(expression) == VECSXP)
    {
        for (int j = 0; j < LENGTH(expression); j++)
            lmm_hybrid_full_check(VECTOR_ELT(expression, j), data, parents);
    }
    else if (TYPEOF(expression) == LANGSXP)
    {
        for (SEXP node = CDR(expression); !isNull(node); node = CDR(node))
            lmm_hybrid_full_check(CAR(node), data, parents);
    }
    else if (TYPEOF(expression) == SYMSXP)
    {
        const char *key = CHAR(PRINTNAME(expression));
        for (int side = 0; side < 2; side++)
            if (!strcmp(key, CHAR(STRING_ELT(parents, side))))
                return;
        SEXP column = mvm_get(data, key);
        if (isNull(column))
            return;
        char first[64], current[64];
        const char *a = lmm_value_string(column, 0, first);
        for (int i = 1; i < LENGTH(column); i++)
        {
            const char *b = lmm_value_string(column, i, current);
            if (!a || !b || strcmp(a, b))
                error("prediction='Full' requires explicit newdata for varying "
                      "covariate '%s'; use predict(..., type='conditional')",
                      key);
        }
    }
}

typedef struct
{
    SEXP source, data;
    SEXP *columns;
    const int *rows;
    int n, total;
    double *estimates;
} lmm_hybrid_prediction_input;

static void lmm_hybrid_prediction_values(SEXP, lmm_hybrid_prediction_input *,
                                         int *);

static SEXP lmm_hybrid_predictions(SEXP object, SEXP mode, int *np)
{
    SEXP data = mvm_get(object, "data"),
         parents = getAttrib(data, install("st.hybrid.parents")),
         model = mvm_get(object, "model"),
         y = mvm_get(mvm_get(model, "specification"), "y"),
         traits = mvm_get(model, "traits");
    int nr = LENGTH(mvm_get(model, "omitted")), nt = LENGTH(traits), n = 0,
        full = !strcmp(CHAR(STRING_ELT(mode, 0)), "Full");
    SEXP levels[2];
    int count[2];
    for (int side = 0; side < 2; side++)
    {
        levels[side] = getAttrib(mvm_get(data, CHAR(STRING_ELT(parents, side))),
                                 R_LevelsSymbol);
        count[side] = LENGTH(levels[side]);
    }
    if (full)
    {
        if (!count[0] || !count[1] || count[0] > INT_MAX / count[1])
            error("Full hybrid prediction exceeds supported row count");
        n = count[0] * count[1];
        lmm_hybrid_full_check(CADDR(mvm_get(object, "fixed")), data, parents);
        lmm_hybrid_full_check(mvm_get(object, "random"), data, parents);
    }
    else
        for (int i = 0; i < nr; i++)
        {
            int missing = 0;
            for (int t = 0; t < nt; t++)
                missing |= ISNAN(mvm_num(y, i + (size_t)nr * t));
            n += missing;
        }
    int *rows = mvm_alloc(n, sizeof(int));
    if (full)
        memset(rows, 0, n * sizeof(int));
    else
    {
        int j = 0;
        for (int i = 0; i < nr; i++)
        {
            int missing = 0;
            for (int t = 0; t < nt; t++)
                missing |= ISNAN(mvm_num(y, i + (size_t)nr * t));
            if (missing)
                rows[j++] = i;
        }
    }
    SEXP names = getAttrib(data, R_NamesSymbol);
    for (int j = 0; n && j < LENGTH(data); j++)
        switch (TYPEOF(VECTOR_ELT(data, j)))
        {
        case REALSXP:
        case INTSXP:
        case LGLSXP:
        case STRSXP:
        case VECSXP:
        case RAWSXP:
            break;
        default:
            error("Unsupported hybrid performance column type");
        }
    const char **keys = mvm_alloc(3 + nt, sizeof(char *));
    keys[0] = CHAR(STRING_ELT(parents, 0));
    keys[1] = CHAR(STRING_ELT(parents, 1));
    keys[2] = "source.row";
    for (int t = 0; t < nt; t++)
    {
        char label[8192];
        st_text_write(label, sizeof(label), "prediction.%s",
                 CHAR(STRING_ELT(traits, t)));
        const char *name = nt == 1 ? "prediction" : label;
        char *copy = mvm_alloc(strlen(name) + 1, sizeof(char));
        strcpy(copy, name);
        keys[3 + t] = copy;
    }
    SEXP out = lmm_dataframe(n, 3 + nt, keys, np);
    lmm_hybrid_prediction_input input = {0};
    input.source = data;
    input.data = out;
    input.rows = rows;
    input.n = n;
    input.total = nr;
    input.columns = mvm_alloc(LENGTH(data), sizeof(SEXP));
    for (int side = 0; side < 2; side++)
    {
        SEXP factor;
        if (full)
        {
            factor = lmm_keep(allocVector(INTSXP, n), np);
            for (int i = 0; i < n; i++)
                INTEGER(factor)[i] = (side ? i % count[1] : i / count[1]) + 1;
            setAttrib(factor, R_LevelsSymbol, levels[side]);
            setAttrib(factor, R_ClassSymbol, lmm_keep(mkString("factor"), np));
        }
        else
            factor = lmm_hybrid_subset(mvm_get(data, keys[side]), rows, n, np);
        SET_VECTOR_ELT(out, side, factor);
        for (int j = 0; j < LENGTH(data); j++)
            if (STRING_ELT(names, j) == STRING_ELT(parents, side))
                input.columns[j] = factor;
    }
    if (n)
    {
        if (nt < 1 || n > INT_MAX / nt)
            error("st.lmm prediction: target dimensions exceed size limits");
        input.estimates = mvm_alloc((size_t)n * nt, sizeof(double));
        lmm_hybrid_prediction_values(object, &input, np);
    }
    SEXP source = lmm_keep(allocVector(INTSXP, n), np);
    for (int i = 0; i < n; i++)
        INTEGER(source)[i] = full ? NA_INTEGER : rows[i] + 1;
    SET_VECTOR_ELT(out, 2, source);
    for (int t = 0; t < nt; t++)
    {
        SEXP prediction = lmm_keep(allocVector(REALSXP, n), np);
        for (int i = 0; i < n; i++)
            REAL(prediction)
            [i] = !full && !ISNAN(mvm_num(y, rows[i] + (size_t)nr * t))
                      ? NA_REAL
                      : input.estimates[i + (size_t)n * t];
        SET_VECTOR_ELT(out, 3 + t, prediction);
    }
    return out;
}

static void lsm_summary_class(SEXP table, int *np);
static void lmm_print_result(SEXP, const lmm_print_options *, int *, int);

static SEXP lmm_printable_tests(SEXP table, const char *title, int type, int *np)
{
    if (isNull(table))
        return R_NilValue;
    SEXP out = lmm_keep(duplicate(table), np);
    lsm_summary_class(out, np);
    setAttrib(out, install("test.kind"), lmm_keep(mkString(title), np));
    if (type > 0)
        setAttrib(out, install("test.type"), lmm_keep(ScalarInteger(type), np));
    return out;
}

static SEXP lmm_printable_random_tests(SEXP table, const char *title, int *np)
{
    if (isNull(table))
    {
        const char *names[] = {"term", "method", "status", "p"};
        table = lmm_dataframe(0, 4, names, np);
        for (int j = 0; j < 4; j++)
            SET_VECTOR_ELT(table, j, allocVector(j < 3 ? STRSXP : REALSXP, 0));
    }
    return lmm_printable_tests(table, title, 0, np);
}

static SEXP lmm_test_text(SEXP column, int row)
{
    if (TYPEOF(column) != STRSXP || row >= LENGTH(column))
        return NA_STRING;
    SEXP value = STRING_ELT(column, row);
    return *CHAR(value) ? value : NA_STRING;
}

static SEXP lmm_canonical_tests(SEXP object, int *np)
{
    SEXP tests = mvm_get(object, "tests");
    const char *tables[] = {"fixed", "random", "manova"};
    const char *names[] = {"effect", "term", "scope", "trait", "method", "status",
                           "reference", "DF", "DF1", "DF2", "F", "LR", "p",
                           "denominator.source", "statistic", "calculation"};
    int nt = LENGTH(mvm_get(mvm_get(object, "model"), "traits"));
    int total = 0;
    for (int part = 0; part < 3; part++)
    {
        int count = LENGTH(mvm_get(mvm_get(tests, tables[part]), "term"));
        if (count > INT_MAX - total)
            error("st.lmm: too many stored tests");
        total += count;
    }
    SEXP out = lmm_dataframe(total, 16, names, np);
    for (int j = 0; j < 16; j++)
        SET_VECTOR_ELT(out, j,
            allocVector(j < 7 || j == 13 || j == 15 ? STRSXP : REALSXP, total));
    int offset = 0, moments = mom_is(object);
    for (int part = 0; part < 3; part++)
    {
        SEXP table = mvm_get(tests, tables[part]),
             terms = mvm_get(table, "term"),
             traits = mvm_get(table, "trait"),
             methods = mvm_get(table, part == 2 ? "test" : "method"),
             statuses = mvm_get(table, "status"),
             calculation = mvm_get(table, "calculation"),
             denominator = mvm_get(table, "denominator");
        if (isNull(denominator))
            denominator = getAttrib(table, install("denominator.source"));
        SEXP columns[] = {mvm_get(table, "DF"), mvm_get(table, "DF1"),
                          mvm_get(table, "DF2"), mvm_get(table, "F"),
                          mvm_get(table, "LR"), mvm_get(table, "p"),
                          mvm_get(table, "statistic")};
        const int positions[] = {7, 8, 9, 10, 11, 12, 14};
        int count = LENGTH(terms);
        int first_joint = !moments && part == 0 && nt > 1 &&
                          count % (nt + 1) == 0
                              ? count - count / (nt + 1) : count;
        for (int i = 0; i < count; i++, offset++)
        {
            SEXP trait = lmm_test_text(traits, i),
                 method = lmm_test_text(methods, i),
                 status = lmm_test_text(statuses, i),
                 calc = lmm_test_text(calculation, i),
                 reference = NA_STRING;
            int joint = part == 2 || (i >= first_joint &&
                        trait != NA_STRING && !strcmp(CHAR(trait), "joint"));
            const char *method_text = CHAR(method);
            if (!strcmp(method_text, "exact"))
                method = mkChar("exact F");
            if (!strcmp(method_text, "parametric bootstrap"))
                reference = mkChar("bootstrap");
            else if (!strcmp(method_text, "LRT"))
                reference = mkChar("chi-square");
            else if (!isNull(columns[3]) && strcmp(method_text, "none"))
                reference = mkChar("F");
            if (part == 2 && calc != NA_STRING)
                status = mkChar(!strcmp(CHAR(calc), "not estimable")
                                    ? "not estimable" : "ok");
            SET_STRING_ELT(VECTOR_ELT(out, 0), offset,
                           mkChar(part == 1 ? "random" : "fixed"));
            SET_STRING_ELT(VECTOR_ELT(out, 1), offset, lmm_test_text(terms, i));
            SET_STRING_ELT(VECTOR_ELT(out, 2), offset,
                           mkChar(joint ? "joint" : trait != NA_STRING
                                               ? "trait" : "term"));
            SET_STRING_ELT(VECTOR_ELT(out, 3), offset, joint ? NA_STRING : trait);
            SET_STRING_ELT(VECTOR_ELT(out, 4), offset, method);
            SET_STRING_ELT(VECTOR_ELT(out, 5), offset, status);
            SET_STRING_ELT(VECTOR_ELT(out, 6), offset, reference);
            for (int j = 0; j < 7; j++)
                REAL(VECTOR_ELT(out, positions[j]))[offset] =
                    mvm_numeric(columns[j]) && i < LENGTH(columns[j])
                        ? mvm_num(columns[j], i) : NA_REAL;
            SET_STRING_ELT(VECTOR_ELT(out, 13), offset,
                           lmm_test_text(denominator, i));
            SET_STRING_ELT(VECTOR_ELT(out, 15), offset, calc);
        }
    }
    return lmm_result_wrap(out, 0, np, 0);
}

static SEXP lmm_manova_tests(SEXP object, SEXP test, int *np)
{
    SEXP table = mvm_get(mvm_get(object, "tests"), "manova"),
         methods = mvm_get(table, "test");
    int n = LENGTH(methods);
    if (!n)
        error("anova.st.lmm: no stored MANOVA tests are available for this fit");
    if (!isNull(test) && (TYPEOF(test) != STRSXP || LENGTH(test) != 1 ||
                          STRING_ELT(test, 0) == NA_STRING))
        error("anova.st.lmm: MANOVA test must be one nonmissing method name");
    SEXP method = isNull(test) ? R_NilValue : STRING_ELT(test, 0);
    int count = 0, *rows = mvm_alloc(n, sizeof(int));
    for (int i = 0; i < n; i++)
        if (isNull(method) || STRING_ELT(methods, i) == method)
            rows[count++] = i;
    if (!count)
        error("anova.st.lmm: MANOVA test must be Pillai, Wilks, "
              "Hotelling-Lawley or Roy");
    const char *names[] = {"term", "method", "statistic", "DF1", "DF2",
                           "F", "p", "calculation"};
    SEXP out = lmm_dataframe(count, 8, names, np);
    for (int j = 0; j < 8; j++)
    {
        SEXP source = j == 1 ? methods : mvm_get(table, names[j]),
             values = lmm_keep(allocVector(TYPEOF(source), count), np);
        if (TYPEOF(source) == STRSXP)
            for (int i = 0; i < count; i++)
                SET_STRING_ELT(values, i, STRING_ELT(source, rows[i]));
        else
            for (int i = 0; i < count; i++)
                REAL(values)[i] = REAL(source)[rows[i]];
        SET_VECTOR_ELT(out, j, values);
    }
    setAttrib(out, install("st.print.manova"), lmm_keep(ScalarLogical(TRUE), np));
    return lmm_result_wrap(out, 0, np, 0);
}

